mapper.select:
SELECT MUST_CHANGE_PASSWORD
FROM TB_EMP
WHERE HOSP_DIV_ID = #{hospitalId}
  AND EMP_ID = #{userId}
  AND ROLE_CD = 'USER'

mapper.update:
UPDATE TB_EMP
SET FAILED_LOGIN_COUNT = 0,
    LOCKED_UNTIL = NULL,
    UPD_DT = CURRENT_TIMESTAMP
WHERE HOSP_DIV_ID = #{hospitalId}
  AND EMP_ID = #{userId}
  AND (
      FAILED_LOGIN_COUNT != 0
      OR LOCKED_UNTIL IS NOT NULL
  )
